#Requires -Version 5.1
<#
.SYNOPSIS
    Self-contained AVD VM size and quota validation.
.DESCRIPTION
    Selects English, Spanish, or Portuguese and executes the complete validation
    engine embedded in this file. It has no external script, repository module,
    OneDrive, Documents, or fixed root-drive temp dependency. Missing modules are staged in
    a unique OS-managed temporary directory that is deleted after execution. The
    dedicated worker process guarantees Azure assembly cleanup from memory on exit.
#>
[CmdletBinding(SupportsShouldProcess = $false)]
param(
    [ValidateSet('English', 'Spanish', 'Portuguese', 'en-US', 'es-VE', 'pt-BR')]
    [string]$Language,
    [Parameter(Mandatory=$false, HelpMessage="Azure Subscription ID")]
    [string]$SubscriptionId,
    [Parameter(Mandatory=$false, HelpMessage="Azure AD Tenant ID")]
    [string]$TenantId,
    [Parameter(Mandatory=$false, HelpMessage="Azure region for VM size discovery")]
    [string]$Location,
    [ValidateRange(1, 128)]
    [int]$MinCores = 1,
    [ValidateRange(1, 512)]
    [int]$MinMemoryGB = 4,
    [ValidateSet("Light", "Medium", "Heavy", "Graphics", "All")]
    [string]$WorkloadType = "All",
    [switch]$IncludePricing,
    [switch]$IncludeOnlyAccelerated,
    [bool]$DeploymentReadyOnly = $true,
    [switch]$ForceReauth,
    [switch]$NonInteractive,
    [switch]$PassThru,
    [switch]$NoExport,
    [switch]$SkipModuleValidation
)

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'

# Embedded source hashes: English=0576F1C4496549D30C5CC21266EF6A4E654770D4A77085921C74FD15CA43FE47; Spanish=D7BE523FEDE65E439C5296BCB39AB2442BF51A2A53FEFE0BE273DE3D5E1B6D24; Portuguese=E33D4EB2D602DBBB4BE9EF839A4EF061402081006EB4F63DDE0E1D9BAD85934E
$embeddedPayloads = @{
    English = ''
    Spanish = ''
    Portuguese = ''
}

function Expand-EmbeddedScript {
    param([Parameter(Mandatory = $true)][string]$Payload)
    $compressed = [Convert]::FromBase64String($Payload)
    $inputStream = New-Object IO.MemoryStream(,$compressed)
    $gzip = New-Object IO.Compression.GZipStream($inputStream, [IO.Compression.CompressionMode]::Decompress)
    $reader = New-Object IO.StreamReader($gzip, [Text.Encoding]::UTF8)
    try { $reader.ReadToEnd() } finally { $reader.Dispose(); $gzip.Dispose(); $inputStream.Dispose() }
}

function Protect-LauncherFile {
    param([Parameter(Mandatory = $true)][string]$Path)
    try {
        $identity = [Security.Principal.WindowsIdentity]::GetCurrent().Name
        $security = New-Object Security.AccessControl.FileSecurity
        $security.SetAccessRuleProtection($true, $false)
        $security.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($identity, 'FullControl', 'Allow')))
        $security.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule('SYSTEM', 'FullControl', 'Allow')))
        Set-Acl -LiteralPath $Path -AclObject $security -ErrorAction Stop
    } catch {
        Write-Verbose "Could not restrict temporary file ACL: $($_.Exception.Message)"
    }
}

$workerMode = $env:AVD01_EMBEDDED_WORKER -eq '1'
if ($workerMode) {
    $parameterFile = $env:AVD01_PARAMETER_FILE
    $outputFile = $env:AVD01_OUTPUT_FILE
    $errorFile = $env:AVD01_ERROR_FILE
    $workerLanguage = $env:AVD01_WORKER_LANGUAGE
    try {
        if (-not $embeddedPayloads.ContainsKey($workerLanguage)) { throw "Unsupported worker language: $workerLanguage" }
        $parameters = Import-Clixml -LiteralPath $parameterFile -ErrorAction Stop
        $env:AVD_REPORT_SCRIPT_NAME = '01_AVD_Validate_VMSizeAndQuota_Launcher'
        $env:PSModulePath = (($env:PSModulePath -split [IO.Path]::PathSeparator) |
            Where-Object { $_ -and $_ -notmatch '(?i)OneDrive|Documents[\\/](WindowsPowerShell|PowerShell)[\\/]Modules' }) -join [IO.Path]::PathSeparator
        Set-Location -LiteralPath $PSScriptRoot
        $source = Expand-EmbeddedScript -Payload $embeddedPayloads[$workerLanguage]
        $engine = [scriptblock]::Create($source)
        $global:LASTEXITCODE = 0
        $result = & $engine @parameters
        $workerExitCode = $global:LASTEXITCODE
        if ($null -ne $result) {
            $result | Export-Clixml -LiteralPath $outputFile -Depth 40 -Force
            Protect-LauncherFile -Path $outputFile
        }
        exit $workerExitCode
    } catch {
        $_ | Out-String | Set-Content -LiteralPath $errorFile -Encoding UTF8 -Force
        Protect-LauncherFile -Path $errorFile
        exit 2
    }
}

if (-not $Language) {
    if ($NonInteractive) {
        $Language = 'English'
    } else {
        do {
            Write-Host ''
            Write-Host 'Select language / Seleccione el idioma / Selecione o idioma' -ForegroundColor Cyan
            Write-Host '  1. English'
            Write-Host '  2. Español'
            Write-Host '  3. Português'
            $languageChoice = Read-Host 'Choice / Opción / Opção [1]'
            if ([string]::IsNullOrWhiteSpace($languageChoice)) { $languageChoice = '1' }
        } until ($languageChoice -in @('1', '2', '3'))
        $Language = @{'1' = 'English'; '2' = 'Spanish'; '3' = 'Portuguese'}[$languageChoice]
    }
}
$normalizedLanguage = if ($Language -in @('Spanish', 'es-VE')) { 'Spanish' } elseif ($Language -in @('Portuguese', 'pt-BR')) { 'Portuguese' } else { 'English' }

$forwardParameters = @{}
foreach ($parameterName in $PSBoundParameters.Keys) {
    if ($parameterName -ne 'Language') { $forwardParameters[$parameterName] = $PSBoundParameters[$parameterName] }
}
$forwardParameters.ForceReauth = $true
if (-not $NoExport) {
    $forwardParameters.ExportExcelPath = Join-Path $PSScriptRoot ("01_AVD_Validate_VMSizeAndQuota_Launcher_{0}.xlsx" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
}

$powerShellExe = (Get-Process -Id $PID -ErrorAction SilentlyContinue).Path
if ([string]::IsNullOrWhiteSpace($powerShellExe) -or -not (Test-Path -LiteralPath $powerShellExe -PathType Leaf)) {
    $powerShellExe = if ($PSVersionTable.PSEdition -eq 'Core') { 'pwsh.exe' } else { 'powershell.exe' }
}

$operationId = [guid]::NewGuid().ToString('N')
$parameterFile = Join-Path ([IO.Path]::GetTempPath()) "AVD01_Parameters_$operationId.clixml"
$outputFile = Join-Path ([IO.Path]::GetTempPath()) "AVD01_Output_$operationId.clixml"
$errorFile = Join-Path ([IO.Path]::GetTempPath()) "AVD01_Error_$operationId.txt"
$workerTempPath = Join-Path ([IO.Path]::GetTempPath()) "AVD01_Temp_$operationId"
$previousEnvironment = @{
    Worker = $env:AVD01_EMBEDDED_WORKER
    Parameters = $env:AVD01_PARAMETER_FILE
    Output = $env:AVD01_OUTPUT_FILE
    Error = $env:AVD01_ERROR_FILE
    Language = $env:AVD01_WORKER_LANGUAGE
    Temp = $env:TEMP
    Tmp = $env:TMP
}
try {
    New-Item -ItemType Directory -Path $workerTempPath -ErrorAction Stop | Out-Null
    $forwardParameters | Export-Clixml -LiteralPath $parameterFile -Depth 20 -Force
    Protect-LauncherFile -Path $parameterFile
    $env:AVD01_EMBEDDED_WORKER = '1'
    $env:AVD01_PARAMETER_FILE = $parameterFile
    $env:AVD01_OUTPUT_FILE = $outputFile
    $env:AVD01_ERROR_FILE = $errorFile
    $env:AVD01_WORKER_LANGUAGE = $normalizedLanguage
    $env:TEMP = $workerTempPath
    $env:TMP = $workerTempPath
    $child = Start-Process -FilePath $powerShellExe -ArgumentList @('-NoLogo', '-NoProfile', '-ExecutionPolicy', 'Bypass', '-File', $PSCommandPath) -Wait -PassThru -NoNewWindow
    $global:LASTEXITCODE = $child.ExitCode
    if (Test-Path -LiteralPath $outputFile -PathType Leaf) { Import-Clixml -LiteralPath $outputFile }
    if ($child.ExitCode -ne 0) {
        $detail = if (Test-Path -LiteralPath $errorFile -PathType Leaf) { Get-Content -LiteralPath $errorFile -Raw } else { "Embedded validation worker exited with code $($child.ExitCode)." }
        throw $detail.Trim()
    }
} finally {
    foreach ($path in @($parameterFile, $outputFile, $errorFile)) {
        if (-not [string]::IsNullOrWhiteSpace([string]$path)) { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
    }
    if (Test-Path -LiteralPath $workerTempPath) {
        Remove-Item -LiteralPath $workerTempPath -Recurse -Force -ErrorAction SilentlyContinue
    }
    $environmentMap = @{AVD01_EMBEDDED_WORKER='Worker';AVD01_PARAMETER_FILE='Parameters';AVD01_OUTPUT_FILE='Output';AVD01_ERROR_FILE='Error';AVD01_WORKER_LANGUAGE='Language';TEMP='Temp';TMP='Tmp'}
    foreach ($name in $environmentMap.Keys) {
        $value = $previousEnvironment[$environmentMap[$name]]
        if ($null -eq $value) { Remove-Item "Env:$name" -ErrorAction SilentlyContinue } else { Set-Item "Env:$name" $value }
    }
}